import path from 'node:path'

export interface ServerConfig {
  databasePath: string
  host: string
  port: number
  staticRoot: string
}

export function loadConfig(
  environment: NodeJS.ProcessEnv = process.env,
  cwd = process.cwd(),
): ServerConfig {
  const production = environment.NODE_ENV === 'production'
  const port = Number(environment.PORT ?? 8080)

  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error('PORT must be an integer between 1 and 65535')
  }

  return {
    databasePath:
      environment.STACKMAP_DB_PATH ??
      (production ? '/config/stackmap.db' : path.join(cwd, '.data', 'stackmap.db')),
    host: environment.HOST ?? '0.0.0.0',
    port,
    staticRoot: path.resolve(environment.STACKMAP_STATIC_ROOT ?? path.join(cwd, 'dist')),
  }
}

import { randomUUID } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import Database from 'better-sqlite3'

const migrations = [
  {
    version: 1,
    name: 'bootstrap infrastructure metadata',
    apply(connection: Database.Database) {
      connection.exec(`
        CREATE TABLE application_metadata (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        ) STRICT;
      `)
      const insert = connection.prepare(
        'INSERT INTO application_metadata (key, value) VALUES (?, ?)',
      )
      insert.run('installation_id', randomUUID())
      insert.run('created_at', new Date().toISOString())
    },
  },
] as const

export interface StackMapDatabase {
  connection: Database.Database
  close: () => void
  installationId: () => string
  schemaVersion: () => number
}

export function openDatabase(filename: string): StackMapDatabase {
  if (filename !== ':memory:') fs.mkdirSync(path.dirname(filename), { recursive: true })
  const connection = new Database(filename)

  try {
    connection.pragma('journal_mode = WAL')
    connection.pragma('foreign_keys = ON')
    connection.pragma('busy_timeout = 5000')
    runMigrations(connection)
  } catch (error) {
    connection.close()
    throw error
  }

  return {
    connection,
    close: () => connection.close(),
    installationId: () =>
      connection
        .prepare("SELECT value FROM application_metadata WHERE key = 'installation_id'")
        .pluck()
        .get() as string,
    schemaVersion: () =>
      (connection.prepare('SELECT MAX(version) FROM schema_migrations').pluck().get() as number) ?? 0,
  }
}

function runMigrations(connection: Database.Database): void {
  connection.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      applied_at TEXT NOT NULL
    ) STRICT;
  `)
  const applied = new Set(
    connection.prepare('SELECT version FROM schema_migrations').pluck().all() as number[],
  )

  for (const migration of migrations) {
    if (applied.has(migration.version)) continue
    connection.transaction(() => {
      migration.apply(connection)
      connection
        .prepare('INSERT INTO schema_migrations (version, name, applied_at) VALUES (?, ?, ?)')
        .run(migration.version, migration.name, new Date().toISOString())
    })()
  }
}

import fs from 'node:fs'
import path from 'node:path'
import fastifyStatic from '@fastify/static'
import Fastify, { type FastifyInstance } from 'fastify'
import type { StackMapDatabase } from './database.js'

export interface BuildAppOptions {
  database: StackMapDatabase
  staticRoot: string
  logger?: boolean
}

export async function buildApp(options: BuildAppOptions): Promise<FastifyInstance> {
  const app = Fastify({ logger: options.logger ?? false })

  app.get('/health', async (_request, reply) => {
    options.database.connection.prepare('SELECT 1').get()
    return reply.send({ status: 'ok' })
  })
  app.get('/api/v1/meta', async () => ({
    application: 'stackmap',
    datastoreAuthority: 'indexeddb',
    installationId: options.database.installationId(),
    schemaVersion: options.database.schemaVersion(),
  }))

  if (fs.existsSync(path.join(options.staticRoot, 'index.html'))) {
    await app.register(fastifyStatic, { root: options.staticRoot, wildcard: false })
    app.get('/*', async (request, reply) => {
      if (request.url.startsWith('/api/')) return reply.code(404).send({ error: 'Not Found' })
      return reply.sendFile('index.html')
    })
  }

  app.addHook('onClose', async () => options.database.close())
  return app
}

